class TargetStress:
    def __init__(self, components: Mapping[str, object], unit: str = "bar") -> None:
        factor = pressure_to_eVA3(1.0, unit)
        schedules = {}
        for component, value in components.items():
            if component not in STRESS_COMPONENTS:
                raise ValueError(f"Unsupported stress component: {component}")
            schedules[component] = _ConvertedPressureSchedule(
                as_schedule(value),
                factor,
            )
        self._schedules = MappingProxyType(schedules)

