class SimulationContext:
    def __init__(
        self,
        target_temp: Optional[float] = None,
        target_stress: Optional[TargetStress] = None,
        constraints: Optional[List[ConstraintLike]] = None,
    ) -> None:
        """Initialize simulation specifications."""
        if target_stress is not None and not isinstance(target_stress, TargetStress):
            raise TypeError("target_stress must be a TargetStress or None")
        self.target_temp: Optional[float] = target_temp
        self.target_stress = target_stress
        self.constraints: List[ConstraintLike] = (
            constraints if constraints is not None else []
        )
    def resolve(self, *, step: int, time: float) -> ResolvedSimulationContext:
        """Resolve scheduled targets into numeric values for one MD step."""
        if self.target_stress is None:
            target_stress = MappingProxyType({})
            target_stress_is_static = True
        else:
            target_stress = self.target_stress.resolve(step=step, time=time)
            target_stress_is_static = self.target_stress.is_static
        return ResolvedSimulationContext(
            target_temp=(self.target_temp.value_at(step=step, time=time)
                         if callable(getattr(self.target_temp, "value_at", None)) else self.target_temp),
            target_stress=target_stress,
            target_stress_is_static=target_stress_is_static,
            constraints=tuple(self.constraints),
            reference_target_temp=(self.target_temp.value_at(step=0, time=0.)
                                   if callable(getattr(self.target_temp, "value_at", None)) else self.target_temp),
        )
    def get_temperature(self, state: StateLike) -> float:
        """Compute instantaneous temperature using active particle DOF."""
        return _temperature(state, self.constraints)

