class PyGASForceModel(ForcePlugin):
    def __init__(self, artifact, config: SamplingConfig, neighbor_list, *, device="cuda", log_dir=None,
                 debug_neighbor_checks=False):
        super().__init__()
        if torch.device(device).type != "cuda" or not torch.cuda.is_available():
            raise RuntimeError("The PyDyn bridge requires real CuPy/PyTorch CUDA")
        self.runtime = BiasRuntime(artifact, config, device=device, log_dir=log_dir)
        self.neighbor_list = neighbor_list
        if type(debug_neighbor_checks) is not bool:
            raise TypeError('debug_neighbor_checks must be bool')
        self.debug_neighbor_checks = debug_neighbor_checks
        self._expected_numbers = None
        self._checked_inputs = False
        cutoff = getattr(neighbor_list, "rc", getattr(neighbor_list, "cutoff", None))
        if cutoff is None or not math.isclose(float(cutoff), config.neighbor_rc, rel_tol=0, abs_tol=1e-12):
            raise ValueError("Sampling neighbor cutoff must equal the declared neighbor_rc")
        self._sim = None
        self._active = False
        self._dirty = False
        self._pending = None
        self._geometry = None
        self._restore_p = None
        self._failed = False
    def validate(self, sim=None):
        if sim is None:
            return True  # ForcePlugin factory validation precedes Simulation binding.
        if type(sim.ensemble) not in (VelocityVerlet, NVTNoseHoover, NVTBerendsen, MTTKNPT):
            raise TypeError("pyGAS v1 supports the built-in non-spin NVE/NVT/MTTK NPT ensembles")
        if not math.isfinite(sim.dt) or sim.dt <= 0:
            raise ValueError("pyGAS requires a finite positive constant timestep")
        if sim.updaters:
            raise ValueError("Biased dynamics does not yet support embedded state updaters")
        if any(type(item) is not RemoveCOMMomentum for item in sim.context.constraints):
            raise TypeError("Only momentum-only RemoveCOMMomentum constraints are supported")
        evaluator = sim.ensemble.force_evaluator
        if not isinstance(evaluator, BiasedForceEvaluator) or evaluator.bias is not self:
            raise ValueError("ensemble must use BiasedForceEvaluator with this same bias instance")
        if self not in sim.hooks or sum(isinstance(hook, PyGASForceModel) for hook in sim.hooks) != 1:
            raise ValueError("Exactly one pyGAS runtime per simulation is supported")
        for op, _ in sim.ensemble.op_list:
            if hasattr(op, "force_evaluator") and op.force_evaluator is not evaluator:
                raise ValueError("Every force-consuming operator must use the biased evaluator")
        if self._sim is not None and self._sim is not sim:
            raise ValueError("A pyGAS runtime cannot be shared between simulations")
    def neighbor_request(self):
        from pydyn.neighbors import NeighborRequest
        return NeighborRequest(self.runtime.config.neighbor_rc, "full", image_mode="minimum",
                               max_neighbors=self.runtime.config.max_neighbors)
    def on_initialize(self, sim):
        self.validate(sim)
        self._sim = sim
        self._dt = sim.dt
        if self._restore_p is not None:
            # RemoveCOMMomentum during setup must not alter a saved full-step momentum.
            sim.state.p = self._restore_p.copy()
            self._restore_p = None
        self._check_geometry(sim.state)
        if self.runtime.last_step >= 0:
            if sim.step_count != self.runtime.last_step:
                raise ValueError("MD and sampling checkpoint steps differ")
            self._set_results(self.runtime.current)
            self._remember_geometry(sim.state)
        else:
            if sim.step_count != 0:
                raise ValueError("A nonzero start step needs a complete sampling checkpoint")
            evaluation = self._evaluate(sim.state, step=0)
            self.runtime.commit(evaluation)
    def before_step(self, sim):
        if self._failed:
            raise RuntimeError("Failed bias runtime cannot continue; restore a complete checkpoint")
        if sim.step_count != self.runtime.last_step:
            raise ValueError("MD and sampling clocks diverged")
        if sim.dt != getattr(self, "_dt", sim.dt):
            raise ValueError("Changing timestep during biased MD is unsupported")
        self._dt = sim.dt
        self._assert_geometry(sim.state)
        self._active, self._dirty, self._pending = True, False, None
    def geometry_changed(self, state, context, fields):
        if not self._active:
            raise RuntimeError("Geometry notification outside an active integration step")
        if self._pending is not None:
            raise RuntimeError("Multiple force/geometry stages in one MD step are unsupported")
        # Coalesce PositionOp + BoxOp. Do not evaluate an intermediate NPT box.
        self._dirty = True
    def after_step(self, sim):
        if self._pending is None or self._dirty:
            raise RuntimeError("No final-geometry bias evaluation was produced for this step")
        self._assert_geometry(sim.state)
        if self._pending.step != sim.step_count:
            raise ValueError("Candidate bias step differs from the completed MD step")
        self.runtime.commit(self._pending)
        self._active, self._pending = False, None
    def on_finalize(self, sim):
        pass  # Log files are opened/closed at committed events, not held by the engine.
    def compute(self, state, context, properties=None):
        if self._sim is None or self._failed:
            raise RuntimeError("Initialize a hooked Simulation before requesting bias properties")
        if state is not self._sim.state:
            raise ValueError("Use BiasRuntime.evaluate for independent frozen-geometry probes")
        if self._dirty:
            self._pending = self._evaluate(state, self._sim.step_count + 1)
            self._dirty = False
        else:
            self._assert_geometry(state)
        requested = self.implemented_properties if properties is None else properties
        if set(requested).difference(self.implemented_properties):
            raise ValueError("pyGAS provides only additive energy, forces and virial")

class BiasedForceEvaluator:
    def __init__(self, base_evaluator, bias: PyGASForceModel):
        if not isinstance(base_evaluator, ForceEvaluator):
            raise TypeError("Use a PyDyn ForceEvaluator; compose multiple biases inside one pyGAS model")
        self._providers = tuple(base_evaluator.registry.group_by_model(bias.implemented_properties))
        if any(not isinstance(model, ForceModel) for model in self._providers):
            raise TypeError("The bridge requires ForceModel physical providers with standard cache fields")
        self.base = base_evaluator
        self.bias = bias
        self.results = {}
    def validate_properties(self, properties):
        self.base.validate_properties(properties)
    def invalidate(self, fields=None, *, state=None, context=None):
        self.base.invalidate(fields, state=state, context=context)
        self.results = {}
    def begin_batch(self):
        self.base.begin_batch()
    def end_batch(self):
        self.base.end_batch()
    def compute(self, state, context, properties=None):
        if self.bias._dirty:
            # Use the current invalidation protocol, including provider metadata
            # bindings. Neighbor safety remains owned by each physical provider.
            self.base.invalidate({"r", "box"}, state=state, context=context)
        physical = self.base.compute(state, context, properties=properties)
        requested = list(physical) if properties is None else list(properties)
        additions = [name for name in requested if name in self.bias.implemented_properties]
        if additions:
            self.bias.compute(state, context, properties=additions)
        # Never += into an array owned by the physical model's cache.
        self.results = {name: physical[name] + self.bias.results[name] if name in additions
                        else physical[name] for name in requested}
        return self.results

