class BiasRuntime:
    def __init__(self, artifact, config: SamplingConfig, *, device="cuda", log_dir=None):
        self.config = config
        self.runner = (_InMemoryRunner(artifact, device) if isinstance(artifact, torch.nn.Module)
                       else ArtifactRunner(artifact, device=device))
        self.device = self.runner.device
        self.neighbor_protocol = getattr(getattr(self.runner, 'model', None), 'neighbor_protocol', 'pairs_v1')
        if self.neighbor_protocol not in ('pairs_v1', 'masked_pairs_v1'):
            raise ValueError('Unknown sampling neighbor protocol')
        if self.neighbor_protocol == 'masked_pairs_v1' and config.mode != 'static':
            raise ValueError('masked_pairs_v1 currently requires static sampling')
        self.last_step = -1
        self.revision = 0
        self._owner = object()
        self.current: dict[str, torch.Tensor] = {}
        self.model_calls = 0
        self.log_dir = Path(log_dir) if log_dir is not None else None
        if self.log_dir is not None:
            for name in ("GASCVlog.txt", "GASCVsteps.txt", "GASGaussian.txt", "OPES_COLVAR", "OPES_KERNELS"):
                if (self.log_dir / name).exists():
                    raise FileExistsError("Use a fresh log directory for each run/restart segment")
        manifest = self.runner.manifest
        if manifest:
            scientific = manifest.get("scientific", {})
            if ("atomic_numbers" in scientific and
                    tuple(scientific["atomic_numbers"]) != config.atomic_numbers):
                raise ValueError("manifest atom order/species mismatch")
            if scientific.get("sampling_mode", config.mode) != config.mode:
                raise ValueError("manifest sampling mode mismatch")
            expected = {"route": config.route, "n_atoms": len(config.atomic_numbers),
                        "cv_size": config.cv_size, "max_neighbors": config.max_neighbors,
                        "neighbor_rc": config.neighbor_rc}
            if config.route != "opes":
                expected["max_cv_nums"] = config.history_capacity
            else:
                expected["opes_kernel_capacity"] = config.kernel_capacity
            for key, value in expected.items():
                if manifest.get(key) != value:
                    raise ValueError(f"manifest {key}={manifest.get(key)!r}, runtime requests {value!r}")
            if self.runner.backend == "torchscript":
                entry = manifest["artifacts"]["torchscript"]
                if hashlib.sha256(self.runner.path.read_bytes()).hexdigest() != entry["sha256"]:
                    raise ValueError("TorchScript artifact hash mismatch")
            # Shared identity across sibling .pt/.pt2, independent of deployment choice/path.
            identity = {"artifacts": {key: item["sha256"] for key, item in manifest["artifacts"].items()},
                        "scientific": manifest["scientific"], "abi_version": manifest["abi_version"]}
        elif isinstance(self.runner, _InMemoryRunner):
            identity = {"native_model_sha256": self.runner.digest}
        else:
            identity = {"legacy_pt_sha256": hashlib.sha256(self.runner.path.read_bytes()).hexdigest()}
        identity["runtime_config"] = asdict(config)
        self.fingerprint = hashlib.sha256(json.dumps(identity, sort_keys=True).encode()).hexdigest()
        if config.mode == "opes":
            if manifest:
                self.state = initial_opes_state_from_manifest(
                    manifest, config.kernel_capacity, device=self.device, dtype=torch.float64)
            else:
                self.state = _clone(self.runner.model.initialize_state(config.kernel_capacity), self.device)
        else:
            self.state = {
                "cv_traj": torch.zeros((config.history_capacity, config.cv_size), dtype=torch.float64, device=self.device),
                "bias_traj": torch.zeros(config.history_capacity, dtype=torch.float64, device=self.device),
                "saved_cv_nums": torch.zeros((), dtype=torch.int32, device=self.device),
            }
        self._initial = _clone(self.state)
    def _deposits(self, step):
        return (self.config.mode in ("metad", "wtmetad") and step > 0
                and step % self.config.deposit_interval == 0)
    def evaluate(self, positions, cell, side_array, *, step=None):
        """Evaluate against committed state without advancing it (also for probes)."""
        return self._evaluate(positions, cell, side_array, step=step, check_inputs=True)
    def evaluate_masked(self, positions, cell, pairs, mask, count, *, step=None):
        return self._evaluate(positions, cell, pairs, step=step, check_inputs=True,
                              pair_mask=mask, pair_count=count)
    def commit(self, evaluation: BiasEvaluation):
        if evaluation.owner is not self._owner or evaluation.revision != self.revision:
            raise ValueError("stale, duplicate, or foreign sampling evaluation")
        if evaluation.step != self.last_step + 1:
            raise ValueError("sampling steps must be committed exactly once, consecutively")
        values = evaluation.values
        self._validate_values(values)
        if self.config.mode == "opes":
            candidate = {key: values[key] for key in OPES_STATE_NAMES}
            self._validate_state(candidate)
            self.state = _clone(candidate)
        elif self._deposits(evaluation.step):
            count = int(self.state["saved_cv_nums"].item())
            if count >= self.config.history_capacity:
                raise OverflowError("MetaD history capacity exhausted")
            self.state["cv_traj"][count].copy_(values["cv_now"])
            self.state["bias_traj"][count].copy_(values["bias"])
            self.state["saved_cv_nums"].fill_(count + 1)
        self.current = _clone({key: value for key, value in values.items() if key not in OPES_STATE_NAMES})
        self.last_step = evaluation.step
        self.revision += 1
        self._write_logs(values)
    def state_dict(self):
        return {"schema": "pygas-runtime-v1", "fingerprint": self.fingerprint,
                "last_step": self.last_step, "revision": self.revision,
                "neighbor_protocol": self.neighbor_protocol,
                "state": _clone(self.state, "cpu"), "current": _clone(self.current, "cpu")}
    def load_state_dict(self, payload):
        if payload.get("neighbor_protocol", "pairs_v1") != self.neighbor_protocol:
            raise ValueError("checkpoint neighbor protocol mismatch")
        if payload.get("schema") != "pygas-runtime-v1" or payload.get("fingerprint") != self.fingerprint:
            raise ValueError("runtime checkpoint/model/configuration mismatch")
        state = _clone(payload["state"], self.device)
        self._validate_state(state)
        last_step, revision = payload["last_step"], payload["revision"]
        if type(last_step) is not int or last_step < -1 or type(revision) is not int or revision != last_step + 1:
            raise ValueError("invalid checkpoint step/revision")
        current = _clone(payload["current"], self.device)
        if last_step >= 0:
            self._validate_values(current)
        elif current:
            raise ValueError("uninitialized checkpoint cannot contain force results")
        self.state, self.current = state, current
        self.last_step, self.revision = last_step, revision
        self._owner = object()  # Invalidate outstanding evaluations, including pre-restore ones.
    def _write_logs(self, values):
        if self.log_dir is None:
            return
        step = self.last_step
        cv = values["cv_now"].cpu().tolist()
        bias = values["bias"].item()
        mean_force = values["forces"].norm(dim=1).mean().item()
        cv_names = [f"cv{i}" for i in range(self.config.cv_size)]
        if self.config.mode == "opes":
            diagnostics = ("extra_bias", "rct", "zed", "neff", "nker", "work", "excluded",
                           "deposited", "merge_count", "logweight", "probability")
            if step % self.config.log_interval == 0:
                self._append("OPES_COLVAR", [step, bias, *cv, mean_force,
                    *(values["opes_" + key].item() for key in diagnostics), values["status"].item()],
                    ["step", "bias", *cv_names, "mean_bias_force", *diagnostics, "status"])
            if values["opes_deposited"].item():
                self._append("OPES_KERNELS", [step, *cv, *values["opes_last_sigma"].cpu().tolist(),
                    values["opes_last_height"].item(), values["opes_logweight"].item(),
                    values["opes_merge_count"].item(), values["opes_nker"].item()],
                    ["step", *cv_names, *(f"sigma{i}" for i in range(self.config.cv_size)),
                     "height", "logweight", "merge_count", "nker"])
        else:
            if step % self.config.log_interval == 0:
                # Preserve the legacy GASCVlog numeric columns for analysis tools.
                # Explicit restart-aware steps belong in a companion file.
                self._append("GASCVlog.txt", [bias, *cv, mean_force],
                             ["bias", *cv_names, "mean_bias_force"])
                self._append("GASCVsteps.txt", [step], ["step"])
            if self._deposits(step):
                self._append("GASGaussian.txt", [bias, *cv])

